// Deterministic board inputs, not an electrical/thermal power simulation.
export const defaultPicoEnvironment=()=>({temperatureC:27,vsys:5,vbus:true});
export function picoEnvironment(config={}){const c={...defaultPicoEnvironment(),...config};if(!Number.isFinite(c.temperatureC)||c.temperatureC< -40||c.temperatureC>125||!Number.isFinite(c.vsys)||c.vsys<0||c.vsys>5.5||typeof c.vbus!=='boolean')throw Error('Pico ortamı: sıcaklık -40…125 °C, VSYS 0…5.5 V ve VBUS açık/kapalı olmalı.');return {temperatureC:c.temperatureC,vsys:c.vsys,vbus:c.vbus};}
export function sampleInternalADC(runtime,channel){const adc=runtime.rp.adc,e=runtime.environment;if(channel===4){adc.channelValues[4]=adc.temperatueEnable?Math.round((0.706-(e.temperatureC-27)*0.001721)/3.3*4095):0;return true;}if(channel===3){if(runtime.board.wireless&&runtime.cyw43?.selected&&runtime.cyw43.powered){runtime.lastADCError='VSYS ölçümü için CYW43 CS hattı serbest olmalı.';runtime.adcErrorAlarm.schedule(2000);return false;}runtime.lastADCError=null;adc.channelValues[3]=Math.round(e.vsys/3/3.3*4095);}return true;}
